import{_ as e,o as a,c as d,a3 as n}from"./chunks/framework.BkJHvlZ8.js";const h=JSON.parse('{"title":"平台概览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/go/overview.md","filePath":"guide/go/overview.md","lastUpdated":1789529774000}'),r={name:"guide/go/overview.md"};function i(o,t,s,l,c,p){return a(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="平台概览" tabindex="-1">平台概览 <a class="header-anchor" href="#平台概览" aria-label="Permalink to &quot;平台概览&quot;">​</a></h1><p>ApeAdmin-Gin 是 ApeAdmin 的 Go 语言实现：后端基于 Gin v1.12 + GORM v1.31，配置使用 Viper v1.21，日志使用 Zap v1.28，前端使用 Vue 3.5 + TypeScript + Vite + Element Plus。业务能力通过插件扩展，核心只负责认证、权限、菜单、日志、数据访问和 AI 能力。</p><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to &quot;解决什么问题&quot;">​</a></h2><ul><li>用统一的用户、角色、菜单和接口权限支撑中后台业务。</li><li>用三级插件体系（编译内置 / 声明式 ZIP / 外部进程）隔离业务代码，支持运行时启停。</li><li>用 MCP 网关将可授权的管理能力安全暴露给 AI Agent。</li><li>用结构化日志、请求追踪和操作日志降低排查成本。</li></ul><h2 id="运行边界" tabindex="-1">运行边界 <a class="header-anchor" href="#运行边界" aria-label="Permalink to &quot;运行边界&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器</span></span>
<span class="line"><span>  ├─ Vue 管理台（/）</span></span>
<span class="line"><span>  └─ Apehub_web 官网（/apehub-web）</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          └─ Gin（/api/v1）</span></span>
<span class="line"><span>               ├─ 核心 API：auth / user / role / menu / dept / plugin</span></span>
<span class="line"><span>               ├─ MCP：tools / resources / prompts / audit-logs</span></span>
<span class="line"><span>               └─ 插件 API：由插件自行挂载</span></span></code></pre></div><p>默认端口 8001，默认账号 admin / admin123。配置文件 <code>configs/config.yaml</code>，入口 <code>cmd/server/main.go</code>。</p><h2 id="目录速览" tabindex="-1">目录速览 <a class="header-anchor" href="#目录速览" aria-label="Permalink to &quot;目录速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目录</th><th>责任</th></tr></thead><tbody><tr><td><code>cmd/server</code></td><td>程序入口，flag 解析 + bootstrap.Run</td></tr><tr><td><code>configs</code></td><td>全局配置（config.yaml）</td></tr><tr><td><code>internal/bootstrap</code></td><td>启动编排：配置→日志→DB→种子→插件→路由→优雅关闭</td></tr><tr><td><code>internal/api</code></td><td>HTTP 路由 + Handler（公开/认证/权限三级分组）</td></tr><tr><td><code>internal/config</code></td><td>Viper 配置结构体</td></tr><tr><td><code>internal/core</code></td><td>核心组件：db / jwt / tokenstore / auditqueue / logger / seed / container</td></tr><tr><td><code>internal/middleware</code></td><td>中间件链：jwt_auth / login_guard / permission / rate_limit 等</td></tr><tr><td><code>internal/model</code></td><td>GORM 模型（sys_ 前缀）</td></tr><tr><td><code>internal/schema</code></td><td>请求/响应 DTO</td></tr><tr><td><code>internal/dal</code></td><td>数据访问层</td></tr><tr><td><code>internal/service</code></td><td>业务逻辑层</td></tr><tr><td><code>internal/mcp</code></td><td>MCP 协议体系（manager / builtin）</td></tr><tr><td><code>internal/plugin</code></td><td>插件系统（interface / registry / manager / eventbus / loader_l2 / zipguard）</td></tr><tr><td><code>internal/pkg</code></td><td>公共工具（response / pagination / tree / utils）</td></tr></tbody></table><h2 id="关键原则" tabindex="-1">关键原则 <a class="header-anchor" href="#关键原则" aria-label="Permalink to &quot;关键原则&quot;">​</a></h2><ol><li>核心能力放在 <code>internal/</code>，业务能力放在插件目录。</li><li>插件的菜单、接口、数据表和静态资源必须使用自己的命名空间。</li><li>页面权限只用于前端体验，后端接口必须再次校验权限。</li><li>生产环境必须修改 <code>jwt.secret</code>，否则密钥熔断机制会拒绝启动。</li></ol>`,11)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
